// Fork addition: catch-all alias registry.
//
// Aliases generated by external clients (Bitwarden's "forwarded email
// alias" generator, addy.io-compatible mode) are registered here so that
// inbound mail for a known alias can be filed into a folder named after
// the site the alias was created for, instead of the generic "unassigned"
// catch-all folder.
//
// Storage: R2, one JSON object per alias at `aliases/{address}.json`,
// mirroring how mailbox settings live at `mailboxes/{address}.json`.
// R2 (unlike KV) is strongly consistent read-after-write, which matters
// because the first mail to a freshly generated alias — the signup
// verification — often arrives seconds after registration.

/** A registered alias, as stored in R2. */
export interface AliasRecord {
	/** Full email address, e.g. "quiet-otter-482@example.com" */
	alias: string;
	/** Local part of the address. */
	local_part: string;
	/** Domain the alias lives on. */
	domain: string;
	/** Raw description sent by the generating client, if any. */
	description: string | null;
	/** Website the alias was generated for, extracted from the description. */
	website: string | null;
	/** ISO timestamp of registration. */
	created: string;
}

/** R2 key for an alias record. */
export const aliasKey = (alias: string) => `aliases/${alias.toLowerCase()}.json`;

/** Slugify into a folder-safe ID (dots become dashes so domains stay readable). */
export function folderSlug(text: string): string {
	return text.toString().toLowerCase()
		.replace(/\./g, "-").replace(/\s+/g, "-").replace(/[^\w-]+/g, "")
		.replace(/--+/g, "-").replace(/^-+/, "").replace(/-+$/, "");
}

// Random local parts use two words + three digits (e.g. "quiet-otter-482").
const WORDS = [
	"amber", "anchor", "apple", "autumn", "basil", "beacon", "birch", "blaze",
	"bloom", "bolt", "breeze", "bridge", "brook", "cactus", "canyon", "cedar",
	"cherry", "cliff", "clover", "coral", "cosmic", "cotton", "crane", "creek",
	"crimson", "dahlia", "delta", "denim", "dolphin", "dune", "eagle", "ember",
	"fern", "fjord", "flame", "flint", "forest", "fossil", "galaxy", "garden",
	"garnet", "ginger", "glacier", "granite", "grove", "harbor", "hazel", "heron",
	"holly", "iris", "ivory", "jade", "jasper", "juniper", "kelp", "lagoon",
	"lantern", "lark", "laurel", "lavender", "lichen", "lilac", "lily", "lynx",
	"maple", "marble", "marsh", "meadow", "mesa", "mint", "moss", "nebula",
	"nectar", "north", "nova", "ocean", "olive", "onyx", "opal", "orchid",
	"otter", "pebble", "pecan", "penguin", "pine", "plum", "poppy", "prairie",
	"quill", "quiver", "raven", "reef", "ridge", "river", "robin", "rosemary",
	"saffron", "sage", "salmon", "sequoia", "shadow", "shore", "silver", "slate",
	"sparrow", "spruce", "storm", "summer", "sunset", "sycamore", "teal", "thunder",
	"tiger", "timber", "topaz", "tulip", "tundra", "valley", "verbena", "violet",
	"walnut", "willow", "winter", "wolf", "zephyr", "beach", "boulder", "comet",
];

function randomInt(maxExclusive: number): number {
	const buf = new Uint32Array(1);
	crypto.getRandomValues(buf);
	return buf[0] % maxExclusive;
}

/** Generate a random alias local part: word-word-###. */
export function generateAliasLocalPart(): string {
	const word = () => WORDS[randomInt(WORDS.length)];
	const digits = String(randomInt(1000)).padStart(3, "0");
	return `${word()}-${word()}-${digits}`;
}

/**
 * Extract the website from a generator description.
 * Bitwarden sends "Website: github.com. Generated by Bitwarden."
 * (or just "Generated by Bitwarden." when no URI is known).
 */
export function extractWebsite(description: string): string | null {
	const match = /Website:\s*(.*?)(?:\s*Generated by|$)/i.exec(description);
	if (!match) return null;
	const site = match[1].trim().replace(/[.,;]+$/, "").trim();
	return site || null;
}

/** Folder (id + display name) that mail for a registered alias is filed into. */
export function aliasFolder(record: AliasRecord): { id: string; name: string } {
	const name = record.website || record.local_part;
	return { id: folderSlug(name), name };
}

/** Look up the first registered alias among the given recipient addresses. */
export async function findAliasRecord(
	bucket: R2Bucket,
	recipients: string[],
): Promise<AliasRecord | null> {
	for (const addr of recipients) {
		const obj = await bucket.get(aliasKey(addr));
		if (obj) return (await obj.json()) as AliasRecord;
	}
	return null;
}

/** Constant-time-ish comparison for bearer tokens. */
export function tokensMatch(a: string, b: string): boolean {
	if (a.length !== b.length) return false;
	let diff = 0;
	for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
	return diff === 0;
}
